    image_patch = ImagePatch(image)
    person_patches = image_patch.find("person")

    if len(person_patches) < 2:
        return image_patch

    # Sort people by horizontal center
    person_patches.sort(key=lambda p: p.horizontal_center)

    # Find the two closest people
    min_distance = float('inf')
    closest_pair = (None, None)

    for i in range(len(person_patches)):
        for j in range(i + 1, len(person_patches)):
            dist = abs(person_patches[i].horizontal_center - person_patches[j].horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_pair = (person_patches[i], person_patches[j])

    # Check if they are wearing similar clothes
    if closest_pair[0].verify_property("shorts", "green") and closest_pair[1].verify_property("shorts", "green"):
        # Determine which one is to the right
        if closest_pair[0].horizontal_center < closest_pair[1].horizontal_center:
            return closest_pair[1]
        else:
            return closest_pair[0]

    return image_patch

