    suitcase_patches = image_patch.find("suitcase")

    if len(suitcase_patches) < 3:
        return image_patch

    # Sort suitcases by their vertical center
    suitcase_patches.sort(key=lambda s: s.vertical_center)

    # Find the white and black suitcases
    white_black_suitcases = [s for s in suitcase_patches if s.verify_property("suitcase", "white") or s.verify_property("suitcase", "black")]

    if len(white_black_suitcases) < 2:
        return image_patch

    # Find the suitcase that is chained to the other two
    chained_suitcase = None
    for s in suitcase_patches:
        if all(not s.overlaps_with(wbs.left, wbs.lower, wbs.right, wbs.upper) for wbs in white_black_suitcases):
            chained_suitcase = s
            break

    if chained_suitcase:
        return chained_suitcase

    return image_patch

